<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">血型遷传</text><text class="nav-icon empty"> </text></view></view><view class="content"><view class="bt-select"><text class="bt-label">父亲血型</text><view class="bt-options"><text class="bt-opt" :class="{active:father==='A'}" @click="father='A';calc()">A</text><text class="bt-opt" :class="{active:father==='B'}" @click="father='B';calc()">B</text><text class="bt-opt" :class="{active:father==='AB'}" @click="father='AB';calc()">AB</text><text class="bt-opt" :class="{active:father==='O'}" @click="father='O';calc()">O</text></view></view><view class="bt-select"><text class="bt-label">母亲血型</text><view class="bt-options"><text class="bt-opt" :class="{active:mother==='A'}" @click="mother='A';calc()">A</text><text class="bt-opt" :class="{active:mother==='B'}" @click="mother='B';calc()">B</text><text class="bt-opt" :class="{active:mother==='AB'}" @click="mother='AB';calc()">AB</text><text class="bt-opt" :class:{active:mother==='O'}" @click="mother='O';calc()">O</text></view></view><view class="bt-result" v-if="result"><text class="bt-r-title">子女可能血型</text><view class="bt-r-types"><text class="bt-r-type" v-for="t in result">{{ t }}</text></view></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const father = ref("A"); const mother = ref("O"); const result = ref([])
var table = { "A-A":["A","O"],"A-B":["A","B","AB","O"],"A-AB":["A","B","AB"],"A-O":["A","O"],"B-A":["A","B","AB","O"],"B-B":["B","O"],"B-AB":["A","B","AB"],"B-O":["B","O"],"AB-A":["A","B","AB"],"AB-B":["A","B","AB"],"AB-AB":["A","B","AB"],"AB-O":["A","B"],"O-A":["A","O"],"O-B":["B","O"],"O-AB":["A","B"],"O-O":["O"] }
function calc() { result.value = table[father.value + "-" + mother.value] || [] }
calc()
function goBack() { uni.navigateBack() }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#e84393,#fd79a8);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:48rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-icon.empty{visibility:hidden}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.bt-select{background:#fff;border-radius:20rpx;padding:24rpx;margin-bottom:24rpx}.bt-label{font-size:28rpx;color:#333;font-weight:600;display:block;margin-bottom:16rpx}.bt-options{display:flex;gap:16rpx}.bt-opt{flex:1;text-align:center;padding:20rpx;background:#f5f5f5;border-radius:12rpx;font-size:30rpx;color:#666;font-weight:600}.bt-opt.active{background:#e84393;color:#fff}.bt-result{background:#fff;border-radius:20rpx;padding:32rpx;text-align:center}.bt-r-title{font-size:26rpx;color:#999;display:block;margin-bottom:24rpx}.bt-r-types{display:flex;gap:24rpx;justify-content:center}.bt-r-type{width:80rpx;height:80rpx;line-height:80rpx;border-radius:50%;background:linear-gradient(135deg,#e84393,#fd79a8);color:#fff;font-size:28rpx;font-weight:700}</style>